//! Independent production death and stale-token boundaries after zero-XP failure.
use gielinor_world::{grinding,tool_crafting::{Recipe,Failure},held_use::{Handler,Scope,Type,Request},inventory::Item,simulation::{World,PlayerData,WorldEvent},stats::Stats,npc::RandomSource,hits::{Hit,Target,Style},CoordGrid};
use std::sync::Arc;
struct Draw{allowed:usize,calls:usize}impl RandomSource for Draw{fn below(&mut self,n:u32)->u32{assert_eq!(n,256);assert!(self.calls<self.allowed,"unexpected completion draw after cancellation");self.calls+=1;255}}
#[test]fn twenty_four_life_and_stale_choice_cases_stop_without_extra_draw_or_reward(){let mut cases=0;for(raw,out,broken)in[(7538,7539,7541),(7536,7537,7540)]{for reverse in[false,true]{for mode in 0..6{println!("PG_CRAB_LIFE_CASE raw={raw} reverse={reverse} mode={mode}");let r=Recipe{exchange:grinding::Recipe{tool:1755,input:raw,output:out,members:true,animation:Some(1280)},level:15,xp_tenths:325,ticks:3,name:"Crab material",action:"carve",failure:Some(Failure{output:broken,xp_tenths:0,low:40,high:240,message:"You accidentally break the crab material."})};let mut stats=Stats::default();stats.set_base(3,10);stats.set_current(3,10);stats.set_base(12,99);stats.set_current(12,99);stats.set_fine_xp(12,130344311).unwrap();let mut w=World::default();w.collision.allocate(3200,3200,0);let mut d=PlayerData::new(1,"Independent crab production life".into(),CoordGrid::new(3200,3200,0).unwrap(),stats);d.xp_rate_hundreds=125;for s in 0..28{d.inventory.restore_slot(s,Some(Item{id:1931,count:1,vars:0})).unwrap();}for(s,id)in[(0,1755),(1,1755),(3,raw),(9,raw),(17,raw),(26,raw)]{d.inventory.restore_slot(s,Some(Item{id,count:1,vars:0})).unwrap();}w.queue_login(1,d).unwrap();w.tick().unwrap();let a=w.actors().next().unwrap();w.set_membership(a,true).unwrap();for id in[1755,raw]{w.held_use_types.insert(id,Type{id,content:-1});}w.held_use_handlers.register(Scope::Types,1755,raw,Handler::ToolCraftingChoices{recipes:Arc::new(vec![r]),cycle_ticks:3}).unwrap();let h=if reverse{Request{selected_slot:17,selected_id:raw,target_slot:0,target_id:1755}}else{Request{selected_slot:0,selected_id:1755,target_slot:17,target_id:raw}};w.prepare_held_use(a,h).unwrap();w.finish_held_use(a,h).unwrap();let q=w.take_tool_crafting_request(a).unwrap().unwrap();w.drain_events();let late=matches!(mode,2|3);let mut rng=Draw{allowed:usize::from(late),calls:0};if late{w.start_tool_crafting_choice(a,q.clone(),0,3).unwrap();for _ in 0..4{w.tick_with_random(&mut rng).unwrap();}assert_eq!(rng.calls,1);assert_eq!(w.data(a).unwrap().inventory.get(17).unwrap().id,broken);assert_eq!(w.data(a).unwrap().stats.fine_xp(12),130344311);assert!(!w.drain_events().iter().any(|e|matches!(e,WorldEvent::SkillAdvanced{..})));}
match mode{0|2=>w.data_mut(a).unwrap().stats.set_current(3,0),1|3=>{w.queue_hit(Target::Player(a),Hit{display:None,source:None,style:Style::Typeless,damage:20},1).unwrap();w.tick_with_random(&mut rng).unwrap();assert_eq!(w.data(a).unwrap().stats.current(3),0);assert!(w.drain_events().iter().any(|e|matches!(e,WorldEvent::DeathRequested(_))));w.data_mut(a).unwrap().stats.set_current(3,10);},4=>{w.close_dialogs(a).unwrap();},_=>{let fresh=Request{selected_slot:26,selected_id:raw,target_slot:0,target_id:1755};w.prepare_held_use(a,fresh).unwrap();w.finish_held_use(a,fresh).unwrap();assert!(w.take_tool_crafting_request(a).unwrap().is_some());}}
let before=w.data(a).unwrap().clone();if !late{let _=w.start_tool_crafting_choice(a,q,0,3);}for _ in 0..12{w.tick_with_random(&mut rng).unwrap();}assert_eq!(rng.calls,usize::from(late));assert_eq!(w.data(a).unwrap().inventory,before.inventory,"mode{mode}");assert_eq!(w.data(a).unwrap().stats,before.stats,"mode{mode}");assert!(!w.drain_events().iter().any(|e|matches!(e,WorldEvent::SkillAdvanced{..})));cases+=1;}}}assert_eq!(cases,24);}
